	CommonParentIRI         = CommonNamespace + "parent"
	CommonRootWorkspaceIRI  = CommonNamespace + "rootWorkspace"
	CommonCreatedIRI        = CommonNamespace + "created"
	CommonCreatedByIRI      = CommonNamespace + "createdBy"
	CommonLastUpdatedIRI    = CommonNamespace + "lastUpdated"
	CommonLastModifiedByIRI = CommonNamespace + "lastModifiedBy"
	CommonHasTagIRI         = CommonNamespace + "hasTag"

