	// IRI from CommonRootWorkspaceIRI, which keeps the same value as a literal for
	// gremlin parity: OWL 2 DL keeps data and object properties disjoint, so one
	// IRI cannot be both.
	CommonWorkspaceIRI = CommonNamespace + "workspace"

	// CommonComponentKeyIRI carries component.componentKey: the short, human-facing
	// identifier Ardoq mints per component ("ACDMPL-1"), which is what a person
	// quotes when they mean one component and what advanced search filters on.
	//
	// The local name is the source column name, as it is for every other built-in
	// here, and it says "componentKey" rather than "key" so the predicate names
	// what it identifies instead of reading as a generic map key. The search
	// translator in ardoq-api aligns to this name.
	CommonComponentKeyIRI = CommonNamespace + "componentKey"

