// builtinComponentProperties are the built-in component properties, in the order
// their shapes are linked onto a component type's node shape.
func builtinComponentProperties() []builtinProperty {
	return []builtinProperty{
		// The source _id. Redundant with the component's IRI, but carried as a
		// property so a query can read it without parsing the IRI — the same reason
		// rootWorkspace is a literal alongside the workspace it names. Advanced
		// search calls it the Ardoq OID, to keep it apart from the component key
		// below, which it calls the Ardoq ID.
		{IRI: commonID, Name: "id", Label: "Ardoq OID", Datatype: xsdString},
		// The component key: the other identifier a component has, and the one a
		// person recognises. Components only — a reference row has no key column.
		// Ardoq names the field `component-key`, not after the column.
		{IRI: commonComponentKey, Name: "component-key", Label: "Ardoq ID", Datatype: xsdString},
		{IRI: commonName, Name: "name", Label: "Name", Datatype: xsdString},
		{IRI: commonDescription, Name: "description", Label: "Description", Datatype: xsdString},
		{IRI: commonCreated, Name: "created", Label: "Created", Datatype: xsdDateTime},
		{IRI: commonCreatedBy, Name: "createdBy", Label: "Created by", TargetClass: userClass},
		{IRI: commonLastUpdated, Name: "lastUpdated", Label: "Last updated", Datatype: xsdDateTime},
		// "Updated by", not "Last modified by": the label is Ardoq's own, and the
		// asymmetry with lastUpdated above is Ardoq's too. The name keeps the source
		// column's spelling, which is what advanced search filters on.
		{IRI: commonLastModifiedBy, Name: "lastModifiedBy", Label: "Updated by", TargetClass: userClass},
		// Both spellings of an entity's workspace share a label, as they do in
		// Ardoq: one is the id as a literal, the other the edge to the resource.
		// Their names differ, so a query can still tell them apart.
		{IRI: commonRootWorkspace, Name: "rootWorkspace", Label: "Workspace", Datatype: xsdString},
		{IRI: commonWorkspace, Name: "workspace", Label: "Workspace", TargetClass: workspaceClass},
		// The one label that is not Ardoq's display wording. `ardoq_parent` is
		// deliberate and long-standing; leave it alone unless whoever owns the
		// consumer that reads it says otherwise. The machine name is still `parent`,
		// so a query for the field by name is unaffected.
		{IRI: commonParent, Name: "parent", Label: "ardoq_parent", TargetClass: componentClass},
		// How the component is drawn, where it overrides its type. Components only:
		// a reference row has no style column, so these stay out of
		// builtinReferenceProperties for the reason componentKey does.
		//
		// All four are xsd:string and nothing narrower. A colour is `#af73ff` in some
		// rows and `rgba(3,42,83,1)` in others, an icon is a sprite name, a shape is a
		// renderer key, and an image is a relative Ardoq attachment path — so image is
		// not xsd:anyURI: it is not a URI a consumer can resolve on its own.
		{IRI: commonColor, Name: "color", Label: "Color", Datatype: xsdString},
		{IRI: commonIcon, Name: "icon", Label: "Icon", Datatype: xsdString},
		{IRI: commonImage, Name: "image", Label: "Image", Datatype: xsdString},
		{IRI: commonShape, Name: "shape", Label: "Shape", Datatype: xsdString},
	}
}

// fieldTypeIdentityOps are the two machine-readable strings every field type
// carries: meta-model/id and meta-model/name.
//
// Every field type carries the same four predicates — these two, rdfs:label and
// rdfs:comment — so one query answers "what is this field called" without knowing
// whether it is built into Ardoq or defined in global_field. For a custom field the
// two differ (an opaque `_id` and the name __ardoqCustomFields is keyed by); for a
// built-in there is only one string and both carry it.
//
// They are the meta-level predicates rather than common/id and common/name because
// those two are themselves built-in field types: a field type described with them
// would be described using itself. See MetaModelIDIRI for the level split.
func fieldTypeIdentityOps(subject, id, name string) []Op {
	var ops []Op
	if id = strings.TrimSpace(id); id != "" {
		ops = append(ops, Op{Type: OpAdd, Subject: subject, Predicate: metaModelID, Object: id, ObjectIsLiteral: true})
	}
	if name = strings.TrimSpace(name); name != "" {
		ops = append(ops, Op{Type: OpAdd, Subject: subject, Predicate: metaModelName, Object: name, ObjectIsLiteral: true})
	}
	return ops
}

