// literalValue is one RDF literal: its lexical form and its datatype IRI. An
// empty Datatype means a plain literal (xsd:string).
type literalValue struct {
	Lexical  string
	Datatype string
}

// literalsForFieldValue renders one custom field value as the RDF literals to
// assert for it.
//
// Two things make this more than a fmt.Sprint. First, the datatype has to match
// what fieldValueRange promised the schema, and a literal whose lexical form does
// not fit its datatype is not merely untidy — GraphLake rejects the update, so a
// single bad source value would stall a store's whole stream. Every conversion
// here therefore falls back to a plain string literal rather than emitting
// something invalid, and says so. An honest string beats a broken number.
//
// Second, values arrive from json.Unmarshal into map[string]any, so the Go types
// are float64, bool, string and []any — not what the field type suggests. A
// Number is a float64, and fmt.Sprint renders float64 in exponent form above 1e6
// ("7.3218541e+07"), which is wrong as a string and invalid as an xsd:decimal.
//
// A SelectMultipleList holds a JSON array and yields one literal per element:
// collapsing them into a single literal loses the values outright, because option
// labels contain spaces and nothing downstream can split them back apart.
func literalsForFieldValue(valueType string, raw any, logCtx fieldValueLogContext) []literalValue {
	normalized := strings.ToLower(strings.TrimSpace(valueType))

	if normalized == "selectmultiplelist" {
		return multiListLiterals(raw, logCtx)
	}
	if normalized == "dateonlyrange" || normalized == "datetimerange" {
		return intervalLiterals(normalized, raw, logCtx)
