// propOps emits the triples for an entity's custom field values.
//
// A value can yield more than one triple: a SelectMultipleList holds an array and
// gets one triple per option. Predicates are emitted in sorted order, and the
// literals under one predicate keep their source order, so the op list is
// deterministic — diffOps compares op lists between the before and after of a CDC
// row, and an unstable order would show up as spurious deletes and inserts.
func propOps(subject string, props propsByPredicate) []Op {
	if props.len() == 0 {
		return nil
	}

	predicates := make([]string, 0, props.len())
	for predicate := range props.byPredicate {
		predicates = append(predicates, predicate)
	}
	sort.Strings(predicates)

	ops := make([]Op, 0, len(predicates))
	for _, predicate := range predicates {
		prop := props.byPredicate[predicate]
		for _, lit := range literalsForFieldValue(prop.valueType, prop.value, prop.logCtx) {
			ops = append(ops, Op{
				Type:            OpAdd,
				Subject:         subject,
				Predicate:       predicate,
				Object:          lit.Lexical,
				ObjectIsLiteral: true,
				ObjectDatatype:  lit.Datatype,
			})
		}
	}
	return ops
}

